using System;
using System.Collections.Generic;
using System.Linq;
using System.Globalization;
public static class CompositeDensityOfflineCheck
{
 static int checks,failures;static void Check(bool ok,string name){checks++;Console.WriteLine((ok?"PASS ":"FAIL ")+name);if(!ok)failures++;}
 static double Roll(string id,int year=0){unchecked{ulong h=14695981039346656037UL;foreach(char c in id){h^=c;h*=1099511628211UL;}h^=(ulong)year*0x9E3779B97F4A7C15UL;h^=h>>30;h*=0xBF58476D1CE4E5B9UL;h^=h>>27;return (h>>11)/9007199254740992.0;}}
 static List<DensityStem> Fixture(int broad,float dbh,double ci){return Enumerable.Range(0,1000).Select(i=>new DensityStem("S"+i.ToString("D5"),i<broad?GrowingSpaceDemandClass.High:GrowingSpaceDemandClass.Reference,dbh,ci)).ToList();}
 static DensityMortalityPlan Plan(List<DensityStem> s,int y=0){Func<string,double> roll=id=>Roll(id,y);return MixedDensityModel.PlanComposite(s,.64f,SitkaSubsetDensitySignal.RequiredDeaths(s,.64f,roll),roll);}
 static void Continuity(){foreach(float dbh in new[]{15f,25f,40f,60f})foreach(double ci in new[]{1.0,3.0,8.0}){double previous=0;int previousBroad=0;foreach(int broad in new[]{0,1,10,50,100}){var s=Fixture(broad,dbh,ci);var p=Plan(s);Console.WriteLine($"CONTINUITY dbh={dbh} ci={ci} sitka={(1000-broad)/10.0}% expected={p.ExpectedAnnualLoss:R} deaths={p.VictimIndices.Count}");if(broad==0){int legacy=SitkaSubsetDensitySignal.RequiredDeaths(s,.64f,id=>Roll(id));Check(p.VictimIndices.Count==legacy,"pure combined signal equals original legacy required count");Check(Math.Abs(p.ExpectedAnnualLoss-legacy/1000.0)<1e-12,"pure pressure equals actual legacy loss fraction");}else Check(Math.Abs(p.ExpectedAnnualLoss-previous)<=2.0*(broad-previousBroad)/1000+.005,"adjacent composition tolerance");if(broad==1){var pure=Plan(Fixture(0,dbh,ci));Check(Math.Abs(p.ExpectedAnnualLoss-pure.ExpectedAnnualLoss)<=.005,"99.9 percent pressure tolerance");var after=s.Where(x=>x.Demand==GrowingSpaceDemandClass.Reference).ToList();var q=Plan(after);Check(Math.Abs(p.ExpectedAnnualLoss-q.ExpectedAnnualLoss)<=.005 && Math.Abs(p.VictimIndices.Count-q.VictimIndices.Count)<=5,"deliberate final broadleaf removal continuity");Check(Math.Abs(p.ExpectedAnnualLoss-q.ExpectedAnnualLoss)<=.005 && Math.Abs(p.VictimIndices.Count-q.VictimIndices.Count)<=5,"natural final broadleaf death same surviving state continuity");}previous=p.ExpectedAnnualLoss;previousBroad=broad;}}}
 static void Neutral(){var s=Fixture(50,40,3);var a=Plan(s);s.Reverse();var b=Plan(s);Check(a.VictimIndices.Select(i=>Fixture(50,40,3)[i].TreeId).OrderBy(x=>x).SequenceEqual(b.VictimIndices.Select(i=>s[i].TreeId).OrderBy(x=>x)),"permutation neutral victim IDs");var baseS=Enumerable.Range(0,100).Select(i=>new DensityStem("N"+i,i%2==0?GrowingSpaceDemandClass.High:GrowingSpaceDemandClass.Intermediate,80,3)).ToList();var flip=baseS.Select(x=>new DensityStem(x.TreeId,x.Demand==GrowingSpaceDemandClass.High?GrowingSpaceDemandClass.Intermediate:GrowingSpaceDemandClass.High,x.DbhCm,x.CompetitionIndex)).ToList();Check(Plan(baseS).VictimIndices.SequenceEqual(Plan(flip).VictimIndices),"class labels never enter neutral allocation at equal occupancy and signal");var f=Fixture(1,25,3);Check(SitkaSubsetDensitySignal.RequiredDeaths(f,.64f,id=>Roll(id))==SitkaSubsetDensitySignal.RequiredDeaths(f.Select(x=>x.Demand==GrowingSpaceDemandClass.High?new DensityStem(x.TreeId,x.Demand,200,100):x).ToList(),.64f,id=>Roll(id)),"broadleaf never enters Sitka subset RD");}
 sealed class Stem{public string Id;public GrowingSpaceDemandClass Demand;public float D,H;}
 static void LongRun(string label,bool recruit){var list=new List<Stem>();int serial=0;for(int i=0;i<1000;i++)list.Add(new Stem{Id="L"+(serial++).ToString("D6"),Demand=label=="Oak"?GrowingSpaceDemandClass.High:label=="Beech"?GrowingSpaceDemandClass.Intermediate:(i%3==0?GrowingSpaceDemandClass.Reference:i%3==1?GrowingSpaceDemandClass.High:GrowingSpaceDemandClass.Intermediate),D=15,H=12});var last=new List<double>();for(int year=1;year<=300;year++){foreach(var s in list){float pd=s.Demand==GrowingSpaceDemandClass.Reference?1.2f:.4f;float ci50=s.Demand==GrowingSpaceDemandClass.Reference?5f:3f;s.D+=pd*(1-s.D/120f)/(1+3/ci50);s.H+=.4f*(1-s.H/40f);}var stems=list.Select(s=>new DensityStem(s.Id,s.Demand,s.D,3)).ToList();var plan=Plan(stems,year);var dead=new HashSet<string>(plan.VictimIndices.Select(i=>stems[i].TreeId));list.RemoveAll(s=>dead.Contains(s.Id));if(recruit){for(int i=0;i<3;i++)list.Add(new Stem{Id="L"+(serial++).ToString("D6"),Demand=label=="Oak"?GrowingSpaceDemandClass.High:label=="Beech"?GrowingSpaceDemandClass.Intermediate:(i%3==0?GrowingSpaceDemandClass.Reference:i%3==1?GrowingSpaceDemandClass.High:GrowingSpaceDemandClass.Intermediate),D=2,H=3.5f});}double occ=MixedDensityModel.Occupancy(list.Select(s=>new DensityStem(s.Id,s.Demand,s.D,3)).ToList(),.64f);Check(!double.IsNaN(occ)&&occ>=0,"long run finite occupancy");if(year>=251)last.Add(occ);if(new[]{25,50,100,200,300}.Contains(year))Console.WriteLine($"LONG_RUN {label} recruitment={recruit} Y{year} n={list.Count} occupancy={occ:R} BA={list.Sum(s=>Math.PI/4*Math.Pow(s.D/100.0,2))/.64:R}");}double mean=last.Average(),slope=Enumerable.Range(0,50).Sum(i=>(i-24.5)*(last[i]-mean))/Enumerable.Range(0,50).Sum(i=>Math.Pow(i-24.5,2));Console.WriteLine($"STABILITY {label} recruitment={recruit} ratio={last.Max()/last.Min():R} slope={slope:R}");Check(last.Max()/last.Min()<=1.2&&Math.Abs(slope)<.005,"predeclared last50 stability "+label+" recruitment="+recruit);}
 public static int Main(){CultureInfo.CurrentCulture=CultureInfo.InvariantCulture;Continuity();Neutral();foreach(var species in new[]{"Oak","Beech","Mixed"}){LongRun(species,false);LongRun(species,true);}Console.WriteLine($"COMPOSITE_DENSITY_{(failures==0?"PASS":"FAIL")} checks={checks} failures={failures}");return failures==0?0:1;}
}
